import {readFile} from 'node:fs/promises';
import {JSDOM} from 'jsdom';
const root=new URL('../src/client/',import.meta.url);
async function experience(member=false,authSettings={},administrator=false,initialHash='',preferences={}){
 const html=await readFile(new URL('index.html',root),'utf8'),dom=new JSDOM(html,{url:'https://momento.example/'+initialHash,runScripts:'outside-only',pretendToBeVisual:true}),{window}=dom,calls=[];
 window.scrollTo=()=>{};window.HTMLMediaElement.prototype.play=()=>Promise.resolve();window.HTMLMediaElement.prototype.pause=()=>{};window.HTMLDialogElement.prototype.showModal=function(){this.open=true};window.HTMLDialogElement.prototype.close=function(){this.open=false;this.onclose?.()};const media=new Map();window.matchMedia=query=>{if(!media.has(query))media.set(query,{matches:query.includes('reduced-motion')?preferences.reduced!==false:preferences.mobile===true,listeners:new Set(),listener(){for(const fn of [...this.listeners])fn()},addEventListener(type,listener){this.listeners.add(listener)},removeEventListener(type,listener){this.listeners.delete(listener)}});return media.get(query)};window.HTMLElement.prototype.scrollIntoView=()=>{};
 window.fetch=async(path,options={})=>{calls.push(path);if(path==='/confidentialite.html')return new Response(await readFile(new URL('confidentialite.html',root),'utf8'));if(path==='/api/auth/config')return Response.json({mode:'supabase',configured:true,providers:[],sms:false,email:false,emailSignup:false,emailMode:'basic',emailRecovery:false,recovery:false,...authSettings});if(path==='/api/me')return member?Response.json({accountRef:'qa-only',persistence:'supabase',profile:member==='incomplete'?null:{name:'<img src=x onerror=alert(1)>',age:29,city:'Paris',gender:preferences.gender||'unspecified'}}):Response.json({error:'authentication_required'},{status:401});if(path.startsWith('/api/service/community/page'))return Response.json({items:[],hasMore:false,next:null});if(path==='/api/service/hosted')return Response.json({premium:false,includedAvailable:false,credits:0,publishingEnabled:false,rooms:[]});if(path==='/api/service/community/overview')return Response.json({memberId:'00000000-0000-4000-8000-000000000001',themes:[],rooms:[],friends:[],requests:[],invitations:[],presence:null,admissionsEnabled:false});if(path.startsWith('/api/service/admin?'))return Response.json({role:'admin',counts:{members:1,rooms:7,openReports:0,suspended:0},reports:[],audit:[],hasMore:false});if(path==='/api/service/admin/test-access')return administrator?Response.json({simulationOnly:true,unlimitedCredits:true,realSessions:false,paymentsEnabled:false}):Response.json({error:'admin_required'},{status:403});if(path==='/api/service/status')return Response.json({admin:administrator,moderator:administrator,premium:false,dailyLimit:1,used:0,bookingLimit:1,readiness:{enabled:false}});throw Error('Unexpected API call '+path)};
 const files=['domain.js','app.js','navigation.js','auth.js','public-seo.js','home-motion.js','themes.js','home.js','account.js','palette.js','media.js','shop-model.js','conversation-model.js','salon-model.js','salon.js','call-ui.js','shop.js','salon-photos.js','room-seats.js','community.js','hosted-rooms.js','live.js','admin.js','call-moments.js','call-setup.js','call-demo.js','roundtable.js'];
 const scripts=await Promise.all(files.map(file=>readFile(new URL(file,root),'utf8')));
 window.ownAvatarMarkup=className=>'<span class="'+className+'">M</span>';window.refreshOwnAvatars=()=>{};window.setupInstall=()=>{};window.profileAppearanceMarkup=()=>'';window.eval(scripts.join("\n")+"\nwindow.cleanState=()=>state;window.ready=()=>accountReady;window.setReady=(v)=>{accountReady=v};window.route=()=>page;window.navigation=MomentoNavigation;window.callRehearsal=()=>callDemoFlow?.state;window.callWallet=()=>salonState?.shop;window.callPeerWallet=()=>callDemoFlow?.peerWallet;window.setCallCredit=(n)=>{salonState.shop.videoCredits=n};window.setCallPremium=(v)=>{salonState.premium=v};window.callVisits=()=>salonState?.visits;window.elapseCall=(seconds,pulse=true)=>{callDemoFlow.wallStart+=seconds*1000;if(pulse)callDemoPulse(callDemoFlow)};window.pauseCallClock=()=>clearInterval(callDemoFlow.clock);window.privateData=()=>({communityData,liveStatus,adminReports:adminReportCache.size});");
 const init=window.initAccount();preferences.inspectInitial?.(window.document);await init;return{dom,window,document:window.document,calls,media};
}
function openCallWithChoices(window){window.go('callDemo');const gender=window.document.querySelector('#callChoiceGender');if(gender){gender.value='all';window.callSetupConfirm()}}
test('call wishes precede a person, devices and the countdown, and only compatible people follow',async()=>{
 const v=await experience(true),{window,document}=v;let devices=0;
 try{
  Object.defineProperty(window.navigator,'mediaDevices',{value:{getUserMedia:async()=>{devices++;throw Error('unexpected device request')}}});
  window.go('callDemo');window.pauseCallClock();
  assert.equal(document.querySelector('.conversation-view').hidden,true);assert.equal(document.querySelector('#callDemoName').textContent,'Vos envies, d’abord.');assert.ok(!document.querySelector('#app').textContent.includes('Camille'));
  window.callDemoStart();await window.callDemoEnableSelected();await window.callDemoToggleDevice('video');
  assert.equal(window.callRehearsal().phase,'preview');assert.equal(devices,0);assert.match(document.querySelector('#callChoiceError').textContent,/genre recherché/);
  document.querySelector('#callChoiceGender').value='man';document.querySelector('#callChoiceMin').value='31';document.querySelector('#callChoiceMax').value='31';document.querySelector('#callChoiceIntent').value='love';
  window.callDemoStart();assert.equal(window.callRehearsal().phase,'date');assert.equal(document.querySelector('#callDemoName').textContent,'Alex');assert.equal(devices,0);assert.equal(document.querySelector('.conversation-view').hidden,false);
 }finally{v.dom.window.close()}
});
